}

Method.Source:
/// <summary>
///    Enables or disables the post button on the lines form.
/// </summary>
protected void setPostMenuButtonEnabled()
{
    next setPostMenuButtonEnabled();

    if (ctrlPostJournalButton && ctrlPostJournalButton.enabled())
    {
        LedgerJournalTable ledgerJournalTable = ledgerJournalEngine.parmLedgerJournalTable();
        boolean enableToPost_bec = !(ledgerJournalTable.AVACopiedWithDifLayer || ledgerJournalTable.AVAPostedWithDifLayer);
        ctrlPostJournalButton.enabled(enableToPost_bec);
    }
}
